function getGreeting(){const t=(new Date).getHours();return t>=5&&t<12?"早上好":t>=12&&t<18?"下午好":"晚上好"}function showNotification(){notificationText.textContent=`${getGreeting()}，欢迎来到butlanys的小站`,notification.style.display="block",setTimeout(()=>{notification.classList.add("show")},10),setTimeout(()=>{hideNotification()},3e3)}function hideNotification(){notification.classList.remove("show"),setTimeout(()=>{notification.style.display="none"},500)}function animateTitle(){siteTitle.classList.add("show")}const notification=document.getElementById("notification"),closeBtn=document.getElementById("close-btn"),siteTitle=document.querySelector(".site-title"),notificationText=document.querySelector("#notification p");closeBtn.addEventListener("click",hideNotification),window.addEventListener("load",()=>{showNotification(),setTimeout(animateTitle,500),outputDiv.textContent=text}),window.addEventListener("load",function(){const t=document.querySelector(".site-title"),e=document.querySelector(".sitebox");t.classList.add("show"),setTimeout(()=>{e.style.animationPlayState="running"},1e3)});